"""Assemble the concise narrative from inspected lab findings and sources."""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
AUDIT = HERE.parent / 'verification/repro_labs_20261012'


def p(text): return {'kind': 'paragraph', 'text': text}
def small(text): return {'kind': 'small', 'text': text}
def h(text): return {'kind': 'subheading', 'text': text}
def table(headers, rows, widths=None):
    return {'kind': 'table', 'headers': headers, 'rows': rows, 'widths': widths or [1]*len(headers)}
def num(value, digits=3): return f'{value:.{digits}f}'.replace('.', ',')


def compose():
    lab1 = json.loads((AUDIT / 'lab1/findings.json').read_text(encoding='utf-8'))
    replay2 = json.loads((AUDIT / 'lab2/replay_summary.json').read_text(encoding='utf-8'))
    lab3 = json.loads((AUDIT / 'lab3/task1_findings.json').read_text(encoding='utf-8'))
    assert lab1['counts']['historical_CSV_byte_identical'] == 90
    assert replay2['csv_files_byte_identical'] == 159
    assert lab3['bytewise_equal_count'] == 51
    original = {float(row['name'].removeprefix('historical_f').replace('p', '.')): row
                for row in lab3['historical'] if '_fine' not in row['name'] and 'single_spike' not in row['name']}
    observed = ['≈14,5', '≈14,5', '≈14,5', '≈17,5', '≈15,5', '≈10', '≈6,5–7', '≈6,5–7']
    frequency_rows = []
    for index, row in enumerate(lab3['calibrated']):
        f = row['frequency_hz']
        old = original[f]['metrics']
        frequency_rows.append([str(f).replace('.', ','), observed[index], num(old['peak_mean']),
                               str(old['spike_rate_hz']).replace('.', ','), num(row['metrics']['peak_mean'])])
    pages = [
      {'title': 'Результат проверки', 'blocks': [
        p('**Внутренняя повторяемость конфигуратора подтверждена. Полная количественная воспроизводимость NeuroNet не достигнута.** Текущая сборка сохранила все проверенные архивные результаты; независимые расчёты подтверждают уравнения и кратковременную пластичность в исследованных режимах. Сетевое сравнение ограничено различиями графов, буферов переноса и численного протокола.'),
        table(['Архивные сценарии', 'Повторено', 'Идентичные CSV'],
              [['ЛР1', '45 из 45', '90 из 90'], ['ЛР2', '43 кольца + 15 популяций', '159 из 159'],
               ['ЛР3', '17 из 17', '51 из 51'], ['Всего', '120 из 120', '300 из 300']], [1.25, 1.7, 1.1]),
        p('Дополнительно проверены протоколы из пользовательских отчётов, частоты реальных пресинаптических спайков и исходная сеть ЛР3. Выполнены независимые проверки решателя и уменьшение шага. Все четыре набора автоматических тестов текущей сборки прошли.'),
        h('Покрытие заданий'),
        table(['Задание', 'Результат в нашей модели', 'Внешнее сравнение'], [
          ['ЛР1 1–2', 'Покой, одиночный ответ, автоколебания', 'Автоколебания согласуются с кадром; Fire! отдельно не подтверждён'],
          ['ЛР1 3', '2/10/20 Гц после настройки; постоянный ток 3,8', 'Период DC согласуется; исходный 30×3 мс даёт другую кратность'],
          ['ЛР1 4', 'Общий и индивидуальный шум, несколько seed', 'Качественное соответствие; шумовые реализации несопоставимы'],
          ['ЛР2 1–2', 'Кольца 3–10 нейронов, веса 1/0,7/0,5/0,2/0; контроль N=11', 'N=10, w=0,7/0,5: режимы различаются; N=11, w=1: циркуляция в обеих моделях'],
          ['ЛР2 3', '400 E + 100 I, два распределения входной степени', 'Пачки есть; графы и частоты пачек различаются'],
          ['ЛР3 1', 'Все восемь частот реальных спайков; фасилитация и депрессия', 'Численные пики зависят от кратности спайков и шага'],
          ['ЛР3 2', 'Исходный граф, 0,1/1/100 Гц, полный сетевой расчёт', 'Перенос без задержек проведения; точная копия не заявляется']
        ], [.75, 1.85, 1.9]),
        small('Основания: методичка, с. 12–24; сохранённые отчёты и изображения NeuroNet; новые журналы расчётов [1–5]. Совпадение CSV означает повтор результата, а не само по себе правильность модели.')
      ]},
      {'title': 'Лабораторная работа 1', 'blocks': [
        p('Выполнен 81 запуск: 45 архивных и 36 дополнительных. Проверены все четыре научных задания, включая пользовательские b=0,27, постоянный ток 3,8 и шум σ=4/4,5. Число спайков в 14 детерминистических конфигурациях совпало с независимым DOP853; изолированный импульс дополнительно проверен Radau [2].'),
        table(['Условие', 'Текущая сборка', 'Данные NeuroNet'], [
          ['RS без входа и шума', 'Спайков нет', 'Состояние покоя'],
          ['b=0,27; I=0', '48 спайков за 5 с; поздний период 105,36 мс', '≈106,9 мс по изображению'],
          ['Постоянный I=3,8', '29 спайков за 5 с; поздний период 178,05 мс', '≈177,7 мс по изображению'],
          ['30×1 мс; 2/10/20 Гц', 'Наш подбор: 6/30/60 спайков на 6/30/60 стимулов', 'В кадрах 2/20 Гц — 30×3 мс; прямого аналога 1 мс нет'],
          ['σ=4 и 4,5', '2,267±0,352 и 3,511±0,324 Гц', 'Больше нерегулярных спайков при росте σ']
        ], [1.15, 1.65, 1.4]),
        small('Периоды на изображениях имеют разрешение около 8 мс/пиксель; полные настройки ручных сеансов неизвестны. Для шума: два нейрона × пять seed × 10 с, анализ 1–10 с; приведены среднее и SD по десяти траекториям. Это данные нашей модели, не частоты, измеренные в NeuroNet.'),
        p('В переборе постоянного тока при I=3,75 поздняя активность отсутствует, при I=3,8 сохраняется. Интервал перехода 3,75–3,8 установлен для данного начального состояния и протокола; универсальный порог им не определяется.'),
        h('Исходный импульс 30×3 мс'),
        p('Его нельзя считать эквивалентом настроенного одиночного ответа. За 3 с стимуляции при 2/10/20 Гц получено 12/60/81 спайк на 6/30/60 импульсов; общая запись — 3,2 с. При 20 Гц чередуются одиночные и двойные ответы. Огибающая Output на пользовательских скриншотах не разрешает близкие спайки.'),
        p('В ранее выполненном ручном контроле NeuroNet при 10 Гц уменьшение Step с 0,5 до 0,025 мс меняло один полный спайк на два. Новые переводы алгоритма Эйлера воспроизводят этот эффект, однако не являются новым запуском оригинальной программы.'),
        h('Численная точность'),
        table(['Опыт', 'Ошибка при 25 мкс', '12,5 мкс', '5 мкс'], [
          ['Автоколебания b=0,27', '1,681 мс', '0,856 мс', '0,356 мс'],
          ['Постоянный ток I=4', '1,138 мс', '0,663 мс', '0,258 мс'],
          ['30×3 мс при 20 Гц', '1,730 мс', '0,355 мс', '0,075 мс']
        ], [1.7, 1, 1, 1]),
        p('Это максимальная ошибка времени соответствующих спайков относительно DOP853. Она уменьшается с шагом, но может превышать один шаг из-за накопления фазового сдвига. Аналитическая TM-проверка 16 002 строк дала ошибку u/x/y не более 1,06·10⁻¹³.'),
        small('Индивидуальное σ=0 отключает шум при общем σ=8; одинаковые явное и наследуемое σ дают идентичные трассы при том же seed и индексе. Шум удерживается 1 мс; совпадение с неизвестным генератором NeuroNet не установлено. Команда Fire! непосредственно не воспроизводилась.')
      ]},
      {'title': 'Лабораторная работа 2', 'blocks': [
        p('Повторены 43 кольцевых и 15 популяционных расчётов, добавлены сетевые контроли. Все архивные CSV и метрики совпали. Синапсы TM: g=20, U=0,5, τI=10 мс, τrec=50 мс, τfacil=1000 мс; STDP выключена [3].'),
        table(['Кольцо и вес', 'Наша модель с TM', 'NeuroNet по изображениям'], [
          ['N=3 и 5; w=1', 'Одиночный проход, затем покой', 'Затухание'],
          ['N=10; w=1', 'Один проход; последний спайк 137,125 мс', 'Кадр подписан N=10, но содержит 11 нейронов; сравнение не прямое'],
          ['N=11; w=1', 'Циркуляция; период 57,625 мс', 'Циркуляция; период ≈71 мс'],
          ['N=10; w=0,7', 'Один проход; последний спайк 155,275 мс', 'Регулярная активность ≈12 Гц'],
          ['N=10; w=0,5', 'Только стартовый нейрон', 'Регулярная активность ≈10 Гц'],
          ['N=10; w=0,2 / 0', 'Только стартовый нейрон', 'При 0,2 затухание; w=0 не выполнялся']
        ], [1, 1.55, 1.45]),
        p('При w=1 переход N=10→11 меняет затухание на циркуляцию; при половинном шаге она сохраняется (57,613 мс). Для N=10, w=0,7/0,5 расхождение реально. У NeuroNet есть параметр скорости и буферы выходов, но точные задержки колец не извлечены; отличаются также шаг и запуск Fire!. Вклад каждого фактора не установлен.'),
        small('Экспоненциальный синапс при N=10, w=0,7 даёт циркуляцию с периодом 49,525 мс. Это другая модель с полным выбросом: первый ток вдвое больше TM при U=0,5, а не изолированное отключение пластичности.'),
        h('Сети из 500 нейронов'),
        table(['Задано входов', 'Наша средняя частота спайков', 'Наша частота пачек', 'NeuroNet фактически'], [
          ['15±2', '28,727±0,442 Гц', '4,933±0,023 Гц', '5577 связей; k=11,154'],
          ['30±3', '46,645±0,386 Гц', '4,200±0,040 Гц', '11 891 связь; k=23,782']
        ], [.75, 1.3, 1.25, 1.35]),
        small('Наша статистика: среднее ± SD между seed 11/42/101, окно 5–30 с, σ=3, обновление шума 1 мс. Счётчики NeuroNet: 29 и 32 пачки примерно за 29 с; если счёт ведётся с начала запуска, это около 1,0 и 1,1 Гц. Единицы и нормировка поля Mean burst frequency не установлены; использованы графики и счётчики.'),
        p('Дополнительный перенос точных графов NeuroNet дал для 5577 / 11 891 связи соответственно 20,882 / 36,229 Гц на нейрон и 5,32 / 5,04 пачки/с. Условия: сброс в покой, σ=3, seed=42, 30 с, окно 5–30 с, без задержек проведения. Общий режим вспышек сохранён, но одного совпадения графа недостаточно для получения ≈1 Гц. Вклад задержек, шума и выделения пачек отдельно не установлен.'),
        p('Уменьшение шага 25→12,5 мкс изменило среднюю частоту исходных больших сетей на 0,19% и 0,34%; частоты пачек сохранились. Индивидуальные последовательности различаются: это статистическая устойчивость, а не сходимость всех траекторий.'),
        small('Длинные опыты выполнял пакетный исполнитель. На одном графе 500 N за 0,2 с он и ядро GUI дали одинаковые 5588 событий; max |ΔV| для четырёх записанных нейронов — 3,25·10⁻¹². GUI поддерживает 1000 нейронов и 50 000 связей; прежний лимит 16 устарел. Для повторения сохраняйте граф: одинаковый seed разных генераторов не обеспечивает одинаковые связи.')
      ]},
      {'title': 'Лабораторная работа 3: частотный ответ', 'blocks': [
        p('Повторены 17 архивных опытов, затем добавлены подбор стимулов, восемь калиброванных частот и три проверки половинного шага. Задание требует заданной частоты именно пресинаптических спайков. При исходном 30×3 мс она не всегда равна частоте стимулятора [4].'),
        table(['Стимулы, Гц', 'NeuroNet 30×3\nоценка пика', 'Наш 30×3\nпик', 'Наш 30×3\nспайков/с', 'Наш 1 мс\nпик'], frequency_rows, [.8, 1.2, 1, 1.1, 1]),
        p('В последнем столбце подтверждён один спайк на каждый импульс в установившемся окне. Ширина 1 мс; амплитуда 30 для 0,1–10 Гц, 40 для 25 Гц, 60 для 50 Гц и 100 для 100 Гц. Это скорректированный протокол задания, а не точное повторение исходного стимула.'),
        {'kind': 'figure', 'path': 'figures/lab3_frequency.png', 'caption': 'Вершина выхода относительно нуля, включая остаточный хвост; не прирост на спайке. Отрезки у NeuroNet 50/100 Гц обозначают визуальный диапазон 6,5–7, а не статистическую погрешность. Линии соединяют проверенные частоты.'},
        p('После длительного покоя одиночный спайк даёт контроль A0=10. Максимум среди восьми калиброванных частот — 16,603 при 5 Гц; при истинных 100 Гц — 4,860. Фасилитация и депрессия подтверждены. Старое значение 6,567 при стимуляторе 100 Гц относится к фактическим 50 спайкам/с.'),
        small('Точные TM-переходы согласуются с u/x/y ядра в пределах 2,23·10⁻¹³ на фактических временах спайков. Это не устраняет ошибку нейронного решателя. При половинном шаге 5/50/100 Гц пики сохранены; max сдвиг событий 0,0125/0,0125/0,025 мс. Контроль NeuroNet ≈14,5 относится к 30×3 мс; число высвобождений в нём точным журналом не подтверждено.')
      ]},
      {'title': 'Лабораторная работа 3: сетевой опыт', 'blocks': []},
      {'title': 'Вывод о воспроизводимости и границах проверки', 'blocks': [
        p('**Конфигуратор пригоден для воспроизводимых численных опытов с реализованными моделями.** Повтор архивных расчётов, независимые решения уравнений, аналитика TM и проверки шага не выявили новой ошибки реализации в проверенных режимах. Однако считать программу количественно эквивалентной NeuroNet для всех опытов ЛР1–3 нельзя.'),
        table(['Уровень проверки', 'Что установлено'], [
          ['Повторяемость', '120 архивных сценариев и 300 CSV без изменений; seed повторяет собственную реализацию шума'],
          ['Независимая точность', 'Совпадение чисел спайков с DOP853; контроль Radau; аналитические TM-переходы'],
          ['Устойчивость при уточнении шага', 'В одиночных нейронных опытах ошибка времени спайков уменьшается; для сетей отдельно проверяются события и статистика'],
          ['Сравнение с NeuroNet', 'Частичное: отдельные периоды и качественные эффекты согласуются; кольца и сетевые показатели расходятся']
        ], [1.4, 3]),
        p('Для строгого количественного сравнения нужны одинаковые граф, начальные состояния и порядок смены стимулов, задержки проведения, шумовой процесс, метод/шаг и определение измеряемой величины. Следующий существенный шаг — поддержка и проверка задержек NeuroNet на фиксированной сети; подгонка амплитуд или числа связей под картинку этого не заменяет.'),
        p('Вывод относится к нейронам Ижикевича и проверенным токовым синапсам. Астроцитарные механизмы и биологическая достоверность не валидировались. STDP в научных опытах ЛР1–3 выключена; прохождение её программных тестов не расширяет область этого отчёта.'),
        h('Источники и проверяемые материалы'),
        small('[1] Лобов и др. Нейрокибернетические принципы управления робототехническими устройствами. Часть 2. ННГУ, 2023. Уравнения с. 5–8, задания с. 12–24. SHA-256 исходного PDF: ce57a4758a90f3a2a9ff9c57f001d5e40363bf02ddb1630a3a2d1ec9efff8af3.'),
        small('[2] Пользовательский labs/lab1_report/Отчёт_ЛР1.md и изображения; новые lab1/findings.json, independent.json, user_comparison.json, run_inventory.json.'),
        small('[3] Пользовательский labs/lab2_report/Отчёт_ЛР2.md и изображения; новые lab2/replay_summary.json, run_manifest.json и findings.json.'),
        small('[4] Пользовательский labs/lab3_report/Отчёт_ЛР3.md; файлы NeuroNet NET_files/STP; новые lab3/task1_findings.json, network_import.json и findings.json.'),
        small('[5] Новые журналы находятся в standalone/network_studio/verification/repro_labs_20261012. Общий provenance.json фиксирует исходники, бинарные файлы и источники; ctest.log подтверждает 4/4 теста. Архивные результаты и пользовательские исходные файлы сохранены.'),
        small('Версия: ветка feature/izhikevich-lab1, рабочие изменения включены. SHA-256 CLI: 4965bb5cc41f13f243bf9823f9c3d6c68c1ab0a77d1677574007003f50342a8e. Одного номера Git-коммита недостаточно для идентификации этой сборки. Время в CSV — секунды; ток Ижикевича — единицы модели.'),
      ]}
    ]
    # Authored only after all three 30-second network runs and their checks finish.
    network_blocks = json.loads((HERE / 'network_report_blocks.json').read_text(encoding='utf-8'))
    assert network_blocks, 'Network report must contain the completed results.'
    pages[4]['blocks'] = network_blocks
    network_path = AUDIT / 'lab3/network_findings.json'
    ftz_path = AUDIT / 'lab3/ftz_findings.json'
    if network_path.exists() and ftz_path.exists():
        network = json.loads(network_path.read_text(encoding='utf-8'))
        diagnostic = json.loads(ftz_path.read_text(encoding='utf-8'))
        if len(network['runs']) == 3 and len(diagnostic['runs']) == 4:
            comparisons = [r['comparison'] for r in diagnostic['runs']]
            if all(c['events']['available'] and c['events']['exact_event_order_and_times_equal']
                   and c['weights']['available'] and c['weights']['all_values_numerically_equal']
                   for c in comparisons):
                maximum_tail_difference = max(c['trace']['max_absolute_difference'] for c in comparisons)
                assert maximum_tail_difference < 1e-300
                minutes = ' / '.join(num(r['wall_s']/60, 1)
                                     for r in sorted(network['runs'], key=lambda r: r['frequency_hz']))
                pages[5]['blocks'].insert(4, small(
                    f'Практическое ограничение: три 30-секундных сетевых опыта штатного ядра заняли {minutes} мин '
                    'при 0,1 / 1 / 100 Гц. В отдельном FTZ/DAZ-контроле того же ядра события и веса совпали; '
                    'расхождения записанных состояний меньше 10⁻³⁰⁰ и относятся к затухающим хвостам. '
                    'Режим обработки крайне малых чисел влияет на скорость. В основных таблицах приведена '
                    'штатная серия; времена под параллельной нагрузкой не являются строгим тестом ускорения.'))
    content = {'title': 'Воспроизводимость лабораторных работ 1–3 в Network Studio',
               'date': 'Сводный отчёт · 12 октября 2026 года', 'pages': pages}
    (HERE / 'report_content.json').write_text(json.dumps(content, ensure_ascii=False, indent=2), encoding='utf-8')


if __name__ == '__main__':
    compose()
